const $=id=>document.getElementById(id),ABC='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const seeds=['01110/10001/10001/11111/10001/10001/10001','11110/10001/10001/11110/10001/10001/11110','01111/10000/10000/10000/10000/10000/01111','11110/10001/10001/10001/10001/10001/11110','11111/10000/10000/11110/10000/10000/11111','11111/10000/10000/11110/10000/10000/10000','01111/10000/10000/10111/10001/10001/01111','10001/10001/10001/11111/10001/10001/10001','11111/00100/00100/00100/00100/00100/11111','00111/00010/00010/00010/10010/10010/01100','10001/10010/10100/11000/10100/10010/10001','10000/10000/10000/10000/10000/10000/11111','10001/11011/10101/10101/10001/10001/10001','10001/11001/11001/10101/10011/10011/10001','01110/10001/10001/10001/10001/10001/01110','11110/10001/10001/11110/10000/10000/10000','01110/10001/10001/10001/10101/10010/01101','11110/10001/10001/11110/10100/10010/10001','01111/10000/10000/01110/00001/00001/11110','11111/00100/00100/00100/00100/00100/00100','10001/10001/10001/10001/10001/10001/01110','10001/10001/10001/10001/10001/01010/00100','10001/10001/10001/10101/10101/11011/10001','10001/10001/01010/00100/01010/10001/10001','10001/10001/01010/00100/00100/00100/00100','11111/00001/00010/00100/01000/10000/11111'];
let state={cols:7,rows:9,gap:18,radius:100,outline:0,liquid:55,mergeH:true,mergeV:true,glyphs:{},selected:'A',sample:'MAKE WAVES',previewSize:80};ABC.split('').forEach((c,i)=>state.glyphs[c]=seeds[i].split('/').flatMap((r,y)=>[...r].flatMap((v,x)=>v==='1'?[(y+1)*16+x+1]:[])));
try{const old=JSON.parse(localStorage.getItem('liquid-type-v1'));if(old&&old.glyphs)Object.assign(state,old)}catch(e){}
let cache={},history=[],drawing=false,paint=true,lastCell=-1,pending=false;
function save(){try{localStorage.setItem('liquid-type-v1',JSON.stringify(state));$('saved').textContent='Saved on this device'}catch(e){$('saved').textContent='Storage unavailable'}}
function snapshot(){history.push(JSON.stringify(state));if(history.length>60)history.shift();$('undo').disabled=false}
function sdf(x,y,cx,cy){let h=(1-state.gap/100)*.5,r=h*state.radius/100,qx=Math.abs(x-cx)-(h-r),qy=Math.abs(y-cy)-(h-r);return Math.hypot(Math.max(qx,0),Math.max(qy,0))+Math.min(Math.max(qx,qy),0)-r}
function smooth(a,b,k){if(!k)return Math.min(a,b);let h=Math.max(k-Math.abs(a-b),0)/k;return Math.min(a,b)-h*h*k*.25}
function contours(c){if(cache[c])return cache[c];let cells=state.glyphs[c].filter(n=>n%16<state.cols&&Math.floor(n/16)<state.rows),set=new Set(cells),pairs=[];for(let n of cells){if(state.mergeH&&set.has(n+1)&&n%16+1<state.cols)pairs.push([n,n+1]);if(state.mergeV&&set.has(n+16))pairs.push([n,n+16])}let step=.1,w=state.cols*10+10,h=state.rows*10+10,values=new Float32Array((w+1)*(h+1)),k=state.liquid/100*.8;
for(let y=0;y<=h;y++)for(let x=0;x<=w;x++){let xx=x*step-.5,yy=y*step-.5,min=10,dist={};for(let n of cells){let d=sdf(xx,yy,n%16+.5,Math.floor(n/16)+.5);dist[n]=d;min=Math.min(min,d)}for(let [a,b]of pairs)min=Math.min(min,smooth(dist[a],dist[b],k));if(state.outline>0)min=Math.max(min,-min-state.outline/100);values[y*(w+1)+x]=min}
let segments=[];let interp=(a,b,va,vb)=>{let t=va/(va-vb);return[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t]};for(let y=0;y<h;y++)for(let x=0;x<w;x++){let pts=[[x,y],[x+1,y],[x+1,y+1],[x,y+1]],v=pts.map(p=>values[p[1]*(w+1)+p[0]]),cuts=[];for(let e=0;e<4;e++){let j=(e+1)%4;if((v[e]<0)!=(v[j]<0))cuts.push(interp(pts[e],pts[j],v[e],v[j]))}if(cuts.length===2)segments.push(cuts);else if(cuts.length===4){segments.push([cuts[0],cuts[1]],[cuts[2],cuts[3]])}}
let key=p=>p.map(v=>v.toFixed(4)).join(','),map=new Map();segments.forEach((s,i)=>s.forEach(p=>{let k=key(p);if(!map.has(k))map.set(k,[]);map.get(k).push(i)}));let used=new Set(),loops=[];segments.forEach((s,i)=>{if(used.has(i))return;let loop=[s[0]],p=s[1];used.add(i);for(let z=0;z<segments.length;z++){loop.push(p);if(key(p)===key(loop[0]))break;let next=(map.get(key(p))||[]).find(n=>!used.has(n));if(next===undefined)break;used.add(next);let seg=segments[next];p=key(seg[0])===key(p)?seg[1]:seg[0]}if(loop.length>3){loop.pop();loops.push(loop.map(p=>[(p[0]*step-.5)*100,(p[1]*step-.5)*100]))}});return cache[c]=loops}
function path(c){return contours(c).map(l=>'M'+l.map(p=>p.map(v=>v.toFixed(2)).join(',')).join('L')+'Z').join('')}
function svg(c,extra=''){return `<svg viewBox="-15 -15 ${state.cols*100+30} ${state.rows*100+30}" ${extra}><path d="${path(c)}" fill="currentColor" fill-rule="evenodd"/></svg>`}
function render(){pending=false;for(let id of ['cols','rows','gap','radius','outline','liquid','previewSize'])$(id).value=state[id];for(let id of ['mergeH','mergeV'])$(id).checked=state[id];for(let id of ['gap','radius','liquid'])$(id+'Val').value=state[id]+'%';$('outlineVal').value=state.outline?state.outline+'%':'Solid';$('sizeVal').value=state.previewSize+' px';$('square').classList.toggle('active',state.radius===0);$('round').classList.toggle('active',state.radius>0);$('glyphName').textContent=state.selected;$('gridMeta').textContent=`${state.cols} × ${state.rows} GRID`;
let grid=$('grid');grid.setAttribute('viewBox',`0 0 ${state.cols*100} ${state.rows*100}`);let cells='';for(let y=0;y<state.rows;y++)for(let x=0;x<state.cols;x++)cells+=`<rect x="${x*100}" y="${y*100}" width="100" height="100" fill="transparent" stroke="#3b4036" stroke-width="1"/><circle cx="${x*100+50}" cy="${y*100+50}" r="2" fill="#49513e"/>`;grid.innerHTML=cells+`<path d="${path(state.selected)}" fill="#d3fb75" fill-rule="evenodd" pointer-events="none"/>`;$('pixelCount').textContent=state.glyphs[state.selected].filter(n=>n%16<state.cols&&Math.floor(n/16)<state.rows).length+' pixels';$('letters').innerHTML=[...ABC].map(c=>`<button class="letter ${c===state.selected?'selected':''}" data-letter="${c}" aria-label="Edit letter ${c}" aria-pressed="${c===state.selected}">${svg(c)}<span>${c}</span></button>`).join('');renderPreview();save()}
function renderPreview(){let size=state.previewSize;$('preview').innerHTML=[...state.sample.toUpperCase()].map(c=>ABC.includes(c)?svg(c,`style="height:${size}px;width:${size*state.cols/state.rows}px"`):`<span style="width:${size*.35}px;height:${size}px"></span>`).join('')}
function schedule(all=false){if(all)cache={};if(!pending){pending=true;requestAnimationFrame(render)}}
function cellAt(e){let r=$('grid').getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*state.cols),y=Math.floor((e.clientY-r.top)/r.height*state.rows);return x>=0&&x<state.cols&&y>=0&&y<state.rows?y*16+x:-1}
function draw(e){let n=cellAt(e);if(n<0||n===lastCell)return;lastCell=n;let g=state.glyphs[state.selected],has=g.includes(n);if(paint&&!has)g.push(n);if(!paint&&has)g.splice(g.indexOf(n),1);delete cache[state.selected];schedule()}
$('grid').onpointerdown=e=>{e.preventDefault();snapshot();drawing=true;lastCell=-1;paint=!state.glyphs[state.selected].includes(cellAt(e));$('grid').setPointerCapture(e.pointerId);draw(e)};$('grid').onpointermove=e=>{if(drawing)draw(e)};$('grid').onpointerup=$('grid').onpointercancel=()=>drawing=false;
$('letters').onclick=e=>{let b=e.target.closest('[data-letter]');if(b){state.selected=b.dataset.letter;render()}};
for(let id of ['cols','rows','gap','radius','outline','liquid','mergeH','mergeV']){$(id).addEventListener('change',()=>save());$(id).oninput=()=>{let input=$(id),v=input.type==='checkbox'?input.checked:Number(input.value);if(id==='cols'||id==='rows'){if(!Number.isInteger(v)||v<3||v>16)return}state[id]=v;schedule(true)}}
$('square').onclick=()=>{snapshot();state.radius=0;schedule(true)};$('round').onclick=()=>{snapshot();state.radius=100;schedule(true)};$('clear').onclick=()=>{snapshot();state.glyphs[state.selected]=[];schedule(true)};$('undo').onclick=()=>{if(history.length){state=JSON.parse(history.pop());$('sample').value=state.sample;schedule(true)}};document.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();$('undo').click()}};
$('sample').value=state.sample;$('sample').oninput=e=>{state.sample=e.target.value;renderPreview();save()};$('previewSize').oninput=e=>{state.previewSize=+e.target.value;$('sizeVal').value=state.previewSize+' px';renderPreview();save()};
function download(data,name,type){let u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast(name+' exported')}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}
$('exportSVG').onclick=()=>{let w=state.cols*100+100,h=state.rows*100+130;download(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w*7} ${h*4}"><title>Liquid alphabet</title>${[...ABC].map((c,i)=>`<g id="glyph-${c}" transform="translate(${i%7*w+30} ${Math.floor(i/7)*h+30})"><path fill="black" fill-rule="evenodd" d="${path(c)}"/></g>`).join('')}</svg>`,'liquid-alphabet.svg','image/svg+xml')};
$('exportOTF').onclick=()=>{try{download(makeOTF(state,[...ABC].map(c=>contours(c))),'Liquid-Regular.otf','font/otf')}catch(e){toast('Font export failed: '+e.message)}};render();
